-- ============================================================
-- รายการข้อหาตามระบบ PTM (ส่วนที่ 3)
-- ============================================================
-- ต้องรัน checkpoint_1_tables.sql และ checkpoint_2_rpc.sql ก่อน
--
-- ตรวจก่อนกด Run: บรรทัดแรกของช่อง editor ต้องเป็นเส้น ==== ชุดนี้
--
-- ที่มา: ไฟล์ "ข้อหาในระบบ PTM.xlsx" ที่ผู้ใช้ส่งมา
--   ในไฟล์มี 571 แถว ตัดชื่อซ้ำออก 10 แถว เหลือ 561 ข้อหา
--
-- ⚠️ ข้อสังเกตเรื่องคุณภาพของไฟล์ต้นทาง แจ้งไว้ให้ไปตรวจกับผู้ส่งออก
--   222 แถวไม่มี Accuse_Code และช่องค่าปรับของแถวเหล่านั้นมีเลข 5 หลัก
--   ซึ่งดูเหมือนรหัสข้อหามากกว่าค่าปรับ เช่น แถว "ไม่จัดให้มีเครื่องดับเพลิง"
--   ค่าปรับเป็น 10034 คล้ายคอลัมน์เลื่อนตอน export
--
--   ไฟล์นี้จึงนำเข้าเฉพาะค่าที่เชื่อถือได้
--     ชื่อข้อหา  - ครบทุกแถว ใช้ได้เต็มที่
--     มาตรา     - ครบทุกแถว
--     รหัส      - ใส่เฉพาะแถวที่มีจริง 343 แถว ที่เหลือเป็น null
--     ค่าปรับ    - ใส่เฉพาะแถวที่เป็นตัวเลขต่ำกว่า 10000 (343 แถว) ที่เหลือ null
--   ไม่เดาเติมให้ เพราะเดาผิดแล้วจะไปโผล่ในใบสั่งจริง
-- ============================================================

set search_path = public, extensions;

alter table cp_charges
  add column if not exists code    text,
  add column if not exists section text,
  add column if not exists fine    int,
  add column if not exists common  boolean not null default false;

-- ต้องมี where เสมอ Supabase เปิด sql_safe_updates ไว้ delete ทั้งตารางจะถูกบล็อก
delete from cp_charges where id is not null;


update cp_charges set grp = 'ตาม PTM' where grp is null or grp <> 'ตาม PTM';

-- ============================================================
-- ทำเครื่องหมายข้อหาที่ใช้บ่อย ให้ขึ้นก่อนในช่องเลือก
-- ============================================================
-- 561 ข้อหาเลื่อนหาทีละอันไม่ไหว ตัวที่ใช้ประจำจึงต้องอยู่บนสุด
-- ยึดตามกลุ่ม รสขม 10 ข้อที่หน่วยใช้อยู่ ดูรูปแบบที่ใช้จับคู่ได้ในบรรทัดล่าง
-- ถ้าเห็นว่าจับคู่ผิดหรือตกหล่น แก้ตรงนี้แล้วรันใหม่ได้เลย ไม่กระทบข้อมูลอื่น
update cp_charges set common = true
where name ilike '%เมาสุรา%'
   or name ilike '%ความเร็วเกิน%'
   or name ilike '%หมวกนิรภัย%'
   or name ilike '%เข็มขัดนิรภัย%'
   or name ilike '%ใบอนุญาตขับขี่%'
   or name ilike '%สัญญาณจราจรไฟสีแดง%'
   or name ilike '%ย้อนศร%'
   or name ilike '%แซง%คับขัน%'
   or name ilike '%โทรศัพท์%';

